package worddata

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io/fs"
	"math"
	"strings"
)

// Semantic embeddings stored next to the word lists (data/lang/embeddings.bin),
// generated by cmd/prepare-embeddings (maintainer-only, see design in
// openspec/changes/semantic-phrases/design.md).
const (
	embeddingsMagic   = "TEMB"
	embeddingsVersion = 1
)

// ErrNoEmbeddings is returned when a language ships no embedded vectors.
var ErrNoEmbeddings = errors.New("worddata: no semantic embeddings for language")

// Embeddings holds L2-normalized float32 vectors for the embedded vocabulary.
type Embeddings struct {
	// Dim is the vector dimensionality.
	Dim int
	// Words are the indexed words, alphabetical.
	Words []string

	index map[string]int
	vecs  []float32 // len(Words) * Dim rows, normalized
}

// LoadEmbeddings reads the embedded vectors for a language.
// Returns ErrNoEmbeddings when the language ships none (custom languages).
func LoadEmbeddings(lang string) (*Embeddings, error) {
	data, err := fs.ReadFile(Words, lang+"/embeddings.bin")
	if errors.Is(err, fs.ErrNotExist) {
		return nil, ErrNoEmbeddings
	}
	if err != nil {
		return nil, err
	}
	return ParseEmbeddings(data)
}

// Has reports whether word has a vector.
func (e *Embeddings) Has(word string) bool {
	_, ok := e.index[strings.ToLower(strings.TrimSpace(word))]
	return ok
}

// Vector returns the normalized vector for word, or nil.
func (e *Embeddings) Vector(word string) []float32 {
	i, ok := e.index[strings.ToLower(strings.TrimSpace(word))]
	if !ok {
		return nil
	}
	return e.vecs[i*e.Dim : (i+1)*e.Dim]
}

// ParseEmbeddings decodes the quantized binary format:
//
//	magic "TEMB" | version byte | dim uint16 LE | count uint32 LE
//	count x (len uint16 LE + word bytes)
//	count x dim int8 rows | count x float32 LE scales
//
// int8 rows store round(v / scale) with scale = maxAbs / 127 per vector.
func ParseEmbeddings(data []byte) (*Embeddings, error) {
	header := 4 + 1 + 2 + 4
	if len(data) < header {
		return nil, fmt.Errorf("worddata: embeddings truncated header (%d bytes)", len(data))
	}
	if string(data[:4]) != embeddingsMagic {
		return nil, errors.New("worddata: embeddings bad magic")
	}
	if data[4] != embeddingsVersion {
		return nil, fmt.Errorf("worddata: embeddings version %d unsupported", data[4])
	}
	dim := int(binary.LittleEndian.Uint16(data[5:7]))
	count := int(binary.LittleEndian.Uint32(data[7:header]))
	if dim <= 0 {
		return nil, errors.New("worddata: embeddings invalid dim")
	}

	off := header
	words := make([]string, count)
	for i := range words {
		if off+2 > len(data) {
			return nil, errors.New("worddata: embeddings truncated word table")
		}
		n := int(binary.LittleEndian.Uint16(data[off:]))
		off += 2
		if off+n > len(data) {
			return nil, errors.New("worddata: embeddings truncated word table")
		}
		words[i] = string(data[off : off+n])
		off += n
	}

	vecBytes := count * dim
	if off+vecBytes+4*count > len(data) {
		return nil, errors.New("worddata: embeddings truncated vectors")
	}
	raw := data[off : off+vecBytes]
	off += vecBytes

	scales := make([]float32, count)
	for i := range scales {
		scales[i] = math.Float32frombits(binary.LittleEndian.Uint32(data[off:]))
		off += 4
	}

	e := &Embeddings{
		Dim:   dim,
		Words: words,
		index: make(map[string]int, count),
		vecs:  make([]float32, count*dim),
	}
	for i, w := range words {
		e.index[strings.ToLower(w)] = i
		base, norm := i*dim, float32(0)
		for j := 0; j < dim; j++ {
			v := float32(int8(raw[base+j])) * scales[i]
			e.vecs[base+j] = v
			norm += v * v
		}
		if norm > 0 {
			inv := 1 / float32(math.Sqrt(float64(norm)))
			for j := 0; j < dim; j++ {
				e.vecs[base+j] *= inv
			}
		}
	}
	return e, nil
}

// EncodeEmbeddings quantizes float32 vectors to the embedded binary format.
// Vectors need not be normalized; they are restored L2-normalized on parse.
func EncodeEmbeddings(dim int, words []string, vecs [][]float32) ([]byte, error) {
	if dim <= 0 || dim > math.MaxUint16 {
		return nil, fmt.Errorf("worddata: dim %d out of range", dim)
	}
	if len(words) != len(vecs) {
		return nil, errors.New("worddata: words/vectors length mismatch")
	}
	if len(words) > math.MaxUint32 {
		return nil, errors.New("worddata: too many words")
	}
	for i, v := range vecs {
		if len(v) != dim {
			return nil, fmt.Errorf("worddata: vector %q has %d dims, want %d", words[i], len(v), dim)
		}
		if len(words[i]) > math.MaxUint16 {
			return nil, fmt.Errorf("worddata: word %q too long", words[i])
		}
	}

	buf := bytes.NewBuffer(make([]byte, 0, 11+len(words)*(2+len(words[0])+dim+4)))
	buf.WriteString(embeddingsMagic)
	buf.WriteByte(embeddingsVersion)
	var le [4]byte
	binary.LittleEndian.PutUint16(le[:2], uint16(dim))
	buf.Write(le[:2])
	binary.LittleEndian.PutUint32(le[:], uint32(len(words)))
	buf.Write(le[:])

	for _, w := range words {
		binary.LittleEndian.PutUint16(le[:2], uint16(len(w)))
		buf.Write(le[:2])
		buf.WriteString(w)
	}

	raw := make([]byte, 0, len(words)*dim)
	scales := make([]float32, 0, len(words))
	for _, v := range vecs {
		maxAbs := float32(0)
		for _, x := range v {
			if a := float32(math.Abs(float64(x))); a > maxAbs {
				maxAbs = a
			}
		}
		if maxAbs == 0 {
			maxAbs = 1
		}
		scale := maxAbs / 127
		for _, x := range v {
			q := int(math.Round(float64(x / scale)))
			q = min(max(q, -127), 127)
			raw = append(raw, byte(int8(q)))
		}
		scales = append(scales, scale)
	}
	buf.Write(raw)
	for _, s := range scales {
		binary.LittleEndian.PutUint32(le[:], math.Float32bits(s))
		buf.Write(le[:])
	}
	return buf.Bytes(), nil
}
